import org.springframework.context.annotation.Configuration
import org.springframework.http.HttpStatus
import org.springframework.web.reactive.function.server.*
import java.time.LocalDateTime

interface RouteConfiguration {
}

@Configuration
class PublicRouteConfiguration(
    private val tracer: Tracer,
    private val workflowChain: WorkflowChain,
    private val userDetailsService: RoamingStatusCheckUserDetailsService,
    private val distributedMsisdnCacheManager: DistributedMsisdnCacheManager,
    private val visitorAuthenticator: VisitorAuthenticator
) : RouteConfiguration {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(PublicRouteConfiguration::class.java)
    }

    @Bean
    fun visitorInfo() = coRouter {
        GET("/visitorInfo/{version}/{msisdn}") { serverRequest ->
            resolveResponse(serverRequest)
        }
    }

    private fun originatingAddress(serverRequest: ServerRequest): Pair<String, String> {
        val origiIp = serverRequest.remoteAddress().map { it.address.hostAddress }
        val termiIp = serverRequest.localAddress().map { it.address.hostAddress }
        val xForwardFor: MutableList<String> = serverRequest.headers().header("X-Forwarded-For")
        return if (xForwardFor.isNotEmpty()) {
            Pair(getRemoteIpFromXForwardedFor(xForwardFor[0].trim()), termiIp.orElse(""))
        } else {
            Pair(origiIp.orElse(""), termiIp.orElse(""))
        }
    }

    private fun getRemoteIpFromXForwardedFor(xForwardedFor: String): String {
        val idx = xForwardedFor.indexOf(',')
        return if (idx > -1) {
            xForwardedFor.substring(0, idx)
        } else {
            xForwardedFor
        }
    }

    @Bean
    fun addUser() = coRouter {
        POST("/user/add") { serverRequest ->
            resolveUserManagementResponse {
                val user = serverRequest.awaitBody<UserRequest>()
                visitorAuthenticator.authenticate(serverRequest, listOf(UserRoles.ADMIN)) {
                    ok().json().bodyValueAndAwait(userDetailsService.addUser(user))
                }
            }
        }
    }

    @Bean
    fun updateUserPassword() = coRouter {
        PUT("/user/update-password/{username}") { serverRequest ->
            resolveUserManagementResponse {
                visitorAuthenticator.authenticate(serverRequest, listOf(UserRoles.ADMIN)) {
                    val username = serverRequest.pathVariable("username")
                    val passwordUpdateRequest = serverRequest.awaitBody<PasswordUpdateRequest>()
                    ok().json().bodyValueAndAwait(userDetailsService.updatePassword(username, passwordUpdateRequest.password))
                }
            }
        }
    }

    @Bean
    fun updateUserStatus() = coRouter {
        PUT("/user/change-status/{username}") { serverRequest ->
            resolveUserManagementResponse {
                visitorAuthenticator.authenticate(serverRequest, listOf(UserRoles.ADMIN)) {
                    val username = serverRequest.pathVariable("username")
                    val userStatus = serverRequest.awaitBody<UserStatus>()
                    ok().json().bodyValueAndAwait(userDetailsService.changeUserStatus(username, userStatus.status))
                }
            }
        }
    }

    @Bean
    fun clearCache() = coRouter {
        DELETE("/clear-cache/{msisdn}") { serverRequest ->
            resolveUserManagementResponse {
                visitorAuthenticator.authenticate(serverRequest, listOf(UserRoles.ADMIN)) {
                    val msisdn = serverRequest.pathVariable("msisdn")
                    val removeFromCache = distributedMsisdnCacheManager.removeFromCache(msisdn)
                    ok().json().bodyValueAndAwait(
                        removeFromCache?.toCacheElement()?: CacheElement()
                    )
                }
            }
        }
    }

    @Bean
    fun clearEntireCache() = coRouter {
        GET("/clear-all-cache") { serverRequest ->
            resolveUserManagementResponse {
                visitorAuthenticator.authenticate(serverRequest, listOf(UserRoles.ADMIN)) {
                    distributedMsisdnCacheManager.removeAllFromCache()
                    ok().json().buildAndAwait()
                }
            }
        }
    }

    private suspend fun resolveResponse(request: ServerRequest): ServerResponse {
        val currentTimeMillis = System.currentTimeMillis()
        val localDateTime = LocalDateTime.now()
        return try {
            val context = generateContext(request, currentTimeMillis, localDateTime)
            visitorAuthenticator.authenticate(request, listOf(UserRoles.USER), context) {
                when (val result = workflowChain.processRequest(context.copy(authenticated=true))) {
                    is RoamingStatusCheckSuccess -> ServerResponse.ok().json().bodyValueAndAwait(result.respBody)
                    is RoamingStatusCheckFailure -> ServerResponse.status(result.httpStatusCode).buildAndAwait()
                }
            }
        } catch (e: DefaultErrorException) {
            ServerResponse.status(e.status).buildAndAwait()
        } catch (ex: Throwable) {
            LOGGER.error("Unexpected error while processing request", ex)
            ServerResponse.status(HttpStatus.INTERNAL_SERVER_ERROR).buildAndAwait()
        }
    }

    private suspend fun generateContext(request: ServerRequest, currentTimeMillis: Long, localDateTime: LocalDateTime): Context {
        val (requestIp, hostIP) = originatingAddress(request)
        val version = request.pathVariable("version")
        val msisdn = request.pathVariable("msisdn")
        val imsi = request.queryParam("IMSI").orElse("")
        val (username) = visitorAuthenticator.decodeAuthenticateHeader(request)
        return Context(
            currentTraceId(),
            requestIp,
            hostIP,
            username,
            msisdn,
            version,
            imsi,
            receivedTimeMillis = currentTimeMillis,
            receivedTime = localDateTime
        )
    }

    suspend fun resolveUserManagementResponse(fn: suspend () -> ServerResponse): ServerResponse {
        return try {
            fn()
        } catch (e: DefaultErrorException) {
            ServerResponse.status(e.status).buildAndAwait()
        } catch (e: Exception) {
            ServerResponse.status(HttpStatus.INTERNAL_SERVER_ERROR).buildAndAwait()
        }
    }

    private fun currentTraceId(): String {
        val span: Span? = tracer.currentSpan()
        return if (span != null) {
            span.context().traceId()
        } else {
            IdGenerator.generateId()
        }
    }
}

