29	import io.micrometer.tracing.Tracer
30	import org.springframework.stereotype.Component
31	import org.springframework.web.reactive.function.server.ServerRequest
32	import java.util.*
33	
34	@Component
35	class VisitorAuthenticator(private val eventLogger: EventLogger,
36	                           private val transLogger: TransLogger,
37	                           private val tracer: Tracer,
38	                           private val passwordService: PasswordService,
39	                           val roamingStatusCheckUserRepo: RoamingStatusCheckUserRepo) {
40	
41	    companion object {
42	        @JvmStatic
43	        private val LOGGER = LoggerFactory.getLogger(PublicRouteConfiguration::class.java)
44	        private const val STEP_NAME = "AuthenticateUser"
45	    }
46	
47	    suspend fun <T> authenticate(serverRequest: ServerRequest, roles: List<UserRoles>, context: Context? = null, fn: suspend () -> T) : T {
48	        LOGGER.debug("Trying to authenticate request")
49	        val (username, password) = decodeAuthenticateHeader(serverRequest)
50	        val userByUserName = roamingStatusCheckUserRepo.getUserByUserName(username)
51	
52	        if (roles.contains(UserRoles.USER)) {
53	            checkUserExists(userByUserName, username, context)
54	            checkUserIsActive(userByUserName, username, context)
55	        } else {
56	            checkUserExists(userByUserName, username)
57	            checkUserIsActive(userByUserName, username)
58	        }
59	
60	        val passwordMatch = passwordService.validatePassword(password, userByUserName?.password?: "")
61	        val rolesValidated = validateRoles(userByUserName?.role, roles)
62	        if (passwordMatch && rolesValidated) {
63	            LOGGER.debug("User [$username] is authorized")
64	            if (roles.contains(UserRoles.USER)) {
65	                if (context != null) {
66	                    addToEventLog(context.copy(authenticated = true), WorkflowStepSuccess())
67	                }
68	            }
69	            return fn()
70	        } else {
71	            throw userIsNotAuthorized(passwordMatch, rolesValidated, roles, username, context?.copy(authenticated = false))
72	        }
73	    }
74	
75	    private fun userIsNotAuthorized(passwordMatch: Boolean, rolesValidated: Boolean, roles: List<UserRoles>,
76	                                    username: String, context: Context?): UnauthorizedException {
77	        val description = getErrorDescription(passwordMatch, rolesValidated)
78	        val unauthorizedException = UnauthorizedException(CommonError(description))
79	        if (roles.contains(UserRoles.USER)) {
80	            if (context != null) {
81	                addToEventLog(context, WorkflowStepFailure(unauthorizedException))
82	                transLogger.printTransLog(context, WorkflowStepFailure(unauthorizedException))
83	            }
84	        }
85	        LOGGER.debug("User [$username] is not authorized")
86	        return unauthorizedException
87	    }
88	
89	    private fun checkUserIsActive(userByUserName: RoamingStatusCheckUser?, username: String, context: Context?) {
90	        if (userByUserName?.active != true) {
91	            val exception = UnauthorizedException(CommonError("User access is revoked"))
92	            LOGGER.debug("User access is revoked [$username]")
93	            if (context != null) {
94	                addToEventLog(context, WorkflowStepFailure(exception))
95	                transLogger.printTransLog(context, WorkflowStepFailure(exception))
96	            }
97	            throw exception
98	        }
99	    }
100	
101	    private fun checkUserExists(userByUserName: RoamingStatusCheckUser?, username: String, context: Context?) {
102	        if (userByUserName == null) {
103	            LOGGER.debug("User doesn't exist [$username]")
104	            val exception = UnauthorizedException(CommonError("User doesn't exist"))
105	            if (context != null) {
106	                addToEventLog(context, WorkflowStepFailure(exception))
107	                transLogger.printTransLog(context ,WorkflowStepFailure(exception))
108	            }
109	            throw exception
110	        }
111	    }
112	
113	    fun addToEventLog(context: Context, workStep: WorkFlowStepResult) {
114	        eventLogger.printEventLog(STEP_NAME, context, workStep)
115	    }
116	
117	    private fun checkUserIsActive(userByUserName: RoamingStatusCheckUser?, username: String) {
118	        if (userByUserName?.active != true) {
119	            val exception = ForbiddenException(CommonError("User access is revoked"))
120	            LOGGER.debug("User access is revoked [$username]")
121	            throw exception
122	        }
123	    }
124	
125	    private fun checkUserExists(userByUserName: RoamingStatusCheckUser?, username: String) {
126	        if (userByUserName == null) {
127	            LOGGER.debug("User doesn't exist [$username]")
128	            val exception = ForbiddenException(CommonError("User doesn't exist"))
129	            throw exception
130	        }
131	    }
132	
133	    private fun getErrorDescription(passwordMatch: Boolean, rolesValidated: Boolean): String {
134	        val description = if (!passwordMatch) {
135	            "Password mismatch"
136	        } else if (!rolesValidated) {
137	            "Role not allowed"
138	        } else {
139	            ""
140	        }
141	        return description
142	    }
143	
144	    fun decodeAuthenticateHeader(serverRequest: ServerRequest): Pair<String, String> {
145	        val authenticateHeader = serverRequest.headers().firstHeader("Authorization")
146	        if (authenticateHeader.isNullOrEmpty()) {
147	            LOGGER.error("Authentication header cannot be null or empty")
148	            throw UnauthorizedException(CommonError("Authentication header cannot be null"))
149	        }
150	        try {
151	            val encodedUserNamePassword = authenticateHeader.substringAfter(" ")
152	            val decode = Base64.getDecoder().decode(encodedUserNamePassword).decodeToString()
153	            val split = decode.split(":")
154	            val username = split[0]
155	            val password = split[1]
156	            return Pair(username, password)
157	        } catch (e: Exception) {
158	            LOGGER.error("Error occurred while decoding authentication header", e)
159	            throw UnauthorizedException(CommonError(e.message))
160	        }
161	    }
162	
163	    private fun validateRoles(userRole: String?, roles: List<UserRoles>)  = if (userRole.isNullOrEmpty()) {
164	            false
165	        } else roles.map { it.name }.contains(userRole)
166	
167	    private fun currentTraceId(): String {
168	        val span: Span? = tracer.currentSpan()
169	        return if (span != null) {
170	            span.context().traceId()
171	        } else {
172	            IdGenerator.generateId()
173	        }
174	    }
175	}
