import java.util.*

@Component
class VisitorAuthenticator(private val eventLogger: EventLogger,
                           private val transLogger: TransLogger,
                           private val tracer: Tracer,
                           private val passwordService: PasswordService,
                           val roamingStatusCheckUserRepo: RoamingStatusCheckUserRepo) {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(PublicRouteConfiguration::class.java)
        private const val STEP_NAME = "AuthenticateUser"
    }

    suspend fun <T> authenticate(serverRequest: ServerRequest, roles: List<UserRoles>, context: Context? = null, fn: suspend () -> T) : T {
        LOGGER.debug("Trying to authenticate request")
        val (username, password) = decodeAuthenticateHeader(serverRequest)
        val userByUserName = roamingStatusCheckUserRepo.getUserByUserName(username)

        if (roles.contains(UserRoles.USER)) {
            checkUserExists(userByUserName, username, context)
            checkUserIsActive(userByUserName, username, context)
        } else {
            checkUserExists(userByUserName, username)
            checkUserIsActive(userByUserName, username)
        }

        val passwordMatch = passwordService.validatePassword(password, userByUserName?.password?: "")
        val rolesValidated = validateRoles(userByUserName?.role, roles)
        if (passwordMatch && rolesValidated) {
            LOGGER.debug("User [$username] is authorized")
            if (roles.contains(UserRoles.USER)) {
                if (context != null) {
                    addToEventLog(context.copy(authenticated = true), WorkflowStepSuccess())
                }
            }
            return fn()
        } else {
            throw userIsNotAuthorized(passwordMatch, rolesValidated, roles, username, context?.copy(authenticated = false))
        }
    }

    private fun userIsNotAuthorized(passwordMatch: Boolean, rolesValidated: Boolean, roles: List<UserRoles>,
                                    username: String, context: Context?): UnauthorizedException {
        val description = getErrorDescription(passwordMatch, rolesValidated)
        val unauthorizedException = UnauthorizedException(CommonError(description))
        if (roles.contains(UserRoles.USER)) {
            if (context != null) {
                addToEventLog(context, WorkflowStepFailure(unauthorizedException))
                transLogger.printTransLog(context, WorkflowStepFailure(unauthorizedException))
            }
        }
        LOGGER.debug("User [$username] is not authorized")
        return unauthorizedException
    }

    private fun checkUserIsActive(userByUserName: RoamingStatusCheckUser?, username: String, context: Context?) {
        if (userByUserName?.active != true) {
            val exception = UnauthorizedException(CommonError("User access is revoked"))
            LOGGER.debug("User access is revoked [$username]")
            if (context != null) {
                addToEventLog(context, WorkflowStepFailure(exception))
                transLogger.printTransLog(context, WorkflowStepFailure(exception))
            }
            throw exception
        }
    }

    private fun checkUserExists(userByUserName: RoamingStatusCheckUser?, username: String, context: Context?) {
        if (userByUserName == null) {
            LOGGER.debug("User doesn't exist [$username]")
            val exception = UnauthorizedException(CommonError("User doesn't exist"))
            if (context != null) {
                addToEventLog(context, WorkflowStepFailure(exception))
                transLogger.printTransLog(context ,WorkflowStepFailure(exception))
            }
            throw exception
        }
    }

    fun addToEventLog(context: Context, workStep: WorkFlowStepResult) {
        eventLogger.printEventLog(STEP_NAME, context, workStep)
    }

    private fun checkUserIsActive(userByUserName: RoamingStatusCheckUser?, username: String) {
        if (userByUserName?.active != true) {
            val exception = ForbiddenException(CommonError("User access is revoked"))
            LOGGER.debug("User access is revoked [$username]")
            throw exception
        }
    }

    private fun checkUserExists(userByUserName: RoamingStatusCheckUser?, username: String) {
        if (userByUserName == null) {
            LOGGER.debug("User doesn't exist [$username]")
            val exception = ForbiddenException(CommonError("User doesn't exist"))
            throw exception
        }
    }

    private fun getErrorDescription(passwordMatch: Boolean, rolesValidated: Boolean): String {
        val description = if (!passwordMatch) {
            "Password mismatch"
        } else if (!rolesValidated) {
            "Role not allowed"
        } else {
            ""
        }
        return description
    }

    fun decodeAuthenticateHeader(serverRequest: ServerRequest): Pair<String, String> {
        val authenticateHeader = serverRequest.headers().firstHeader("Authorization")
        if (authenticateHeader.isNullOrEmpty()) {
            LOGGER.error("Authentication header cannot be null or empty")
            throw UnauthorizedException(CommonError("Authentication header cannot be null"))
        }
        try {
            val encodedUserNamePassword = authenticateHeader.substringAfter(" ")
            val decode = Base64.getDecoder().decode(encodedUserNamePassword).decodeToString()
            val split = decode.split(":")
            val username = split[0]
            val password = split[1]
            return Pair(username, password)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while decoding authentication header", e)
            throw UnauthorizedException(CommonError(e.message))
        }
    }

    private fun validateRoles(userRole: String?, roles: List<UserRoles>)  = if (userRole.isNullOrEmpty()) {
            false
        } else roles.map { it.name }.contains(userRole)

    private fun currentTraceId(): String {
        val span: Span? = tracer.currentSpan()
        return if (span != null) {
            span.context().traceId()
        } else {
            IdGenerator.generateId()
        }
    }
}

