package hms.core.m1.rsc.rscservice.connectors

import hms.common.snmp.log.utils.manager.CommonSNMPManager
import hms.core.m1.rsc.rscservice.error.ConnectionError
import hms.core.m1.rsc.rscservice.error.InternalErrorException
import hms.smpl.connector.ExecutionContext
import hms.smpl.connector.command.RequestTemplate
import hms.smpl.connector.processor.CommandProcessor
import hms.smpl.connector.xml.xpath.DataExtractPoint
import hms.smpl.connector.xml.xpath.TagData
import io.github.resilience4j.ratelimiter.annotation.RateLimiter
import kotlinx.coroutines.coroutineScope
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component

interface SpmlConnectorAdapter {
    suspend fun getSpmlData(msisdn: String, type: CallType): SpmlData?
    suspend fun getSpmlSearchResponse(msisdn: String): SpmlData?
    suspend fun multiSimCheckRequest(msisdn: String): SpmlData
    suspend fun sendRequest(requestTemplate: RequestTemplate, executionContext: ExecutionContext): List<Map<String, TagData>>
}

enum class CallType {
    SEARCH_REQUEST,
    MEMBER_CHECK_REQUEST
}

@Component
class DefaultSpmlConnectorAdapter(val commandProcessor: CommandProcessor,
                                  @Value("\${service-api.msisdn-validations.not-found-msisdn-error-codes}") val notFoundErrorCodes: List<String>) : SpmlConnectorAdapter {
    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(DefaultSpmlConnectorAdapter::class.java)
        const val SEARCH_REQUEST_TEMPLATE_NAME: String = "search_request.xml"
        const val HRL_MSISDN_NOT_FOUND_XPATH_PATTERN: String = "searchResponse"
        const val HRL_MSISDN_NOT_FOUND_PLACE_HOLDER: String = "searchResponse"

        const val MSISDN_OF_VLR_XPATH_PATTERN: String = "searchResponse/objects/hlr/vlrMobData/isdnNumberOfVLR"
        const val MSISDN_OF_VLR_PLACE_HOLDER: String = "isdnNumberOfVLR"

        const val MSISDN_OF_CALL_BARRING_XPATH_PATTERN: String = "searchResponse/objects/hlr/odboc"
        const val MSISDN_OF_CALL_BARRING_PLACE_HOLDER: String = "odboc"

        const val MSISDN_OF_HLR_XPATH_PATTERN: String = "searchResponse/objects/hlr"
        const val MSISDN_OF_HLR_PLACE_HOLDER: String = "hlr"

        const val MULTI_SIM_MEMBER_CHECK_REQUEST_TEMPLATE_NAME: String = "multi_sim_member_check_request.xml"
        const val MSISDN_OF_MEMBER_CHECK_XPATH_PATTERN: String = "searchResponse/objects/member/msisdn"
        const val MSISDN_OF_MEMBER_CHECK_PLACE_HOLDER: String = "msisdn"

        const val REQUEST_MSISDN_PLACE_HOLDER: String = "msisdn"
        const val ERROR_CODE_ATTRIBUTE_NAME: String = "errorCode"
    }

    @RateLimiter(name = "spml-requests")
    override suspend fun getSpmlData(msisdn: String, type: CallType) : SpmlData? {
        return when (type) {
            CallType.SEARCH_REQUEST -> {
                getSpmlSearchResponse(msisdn)
            }
            CallType.MEMBER_CHECK_REQUEST -> {
                multiSimCheckRequest(msisdn)
            }
        }
    }

    override suspend fun getSpmlSearchResponse(msisdn: String): SpmlData? {
        LOGGER.info("Trying to find whether msisdn [{}] exists in the HLR", msisdn)
        return try {
            val executionContext = ExecutionContext()
            val requestTemplate = RequestTemplate(SEARCH_REQUEST_TEMPLATE_NAME)
            val dataExtractPoint = DataExtractPoint(HRL_MSISDN_NOT_FOUND_PLACE_HOLDER, HRL_MSISDN_NOT_FOUND_XPATH_PATTERN)
            val dataExtractPointVlr = DataExtractPoint(MSISDN_OF_VLR_PLACE_HOLDER, MSISDN_OF_VLR_XPATH_PATTERN)
            val dataExtractPointCallBarring = DataExtractPoint(MSISDN_OF_CALL_BARRING_PLACE_HOLDER, MSISDN_OF_CALL_BARRING_XPATH_PATTERN)
            val dataExtractPointHlr = DataExtractPoint(MSISDN_OF_HLR_PLACE_HOLDER, MSISDN_OF_HLR_XPATH_PATTERN)

            executionContext.putString(REQUEST_MSISDN_PLACE_HOLDER, msisdn)
            requestTemplate.mandatoryDataExtractPointList = listOf(dataExtractPoint, dataExtractPointVlr, dataExtractPointCallBarring, dataExtractPointHlr)
            val sendRequest = sendRequest(requestTemplate, executionContext)
            val responses = if (sendRequest.isNotEmpty()) {
                sendRequest[0]
            } else {
                mapOf()
            }
            LOGGER.debug("Error response found [{}]", responses)
            resolveSpmlData(responses, msisdn)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting SPML response", e)
            throw InternalErrorException(ConnectionError(e.cause?.cause?.message?: e.message))
        }
    }

    private fun resolveSpmlData(responses: Map<String, TagData>, msisdn: String): SpmlData? {
        val tagDataList = responses.values.toList()
        return if (tagDataList.isNotEmpty()) {
            val tagData = tagDataList[0]
            val errorCode = tagData.attributes[ERROR_CODE_ATTRIBUTE_NAME]
            if (!notFoundErrorCodes.contains(errorCode)) {
                val vlrValues = responses["${MSISDN_OF_VLR_PLACE_HOLDER}-0"]?.value
                val callBarringValues = responses["${MSISDN_OF_CALL_BARRING_PLACE_HOLDER}-0"]?.value
                val hlrData = responses["${MSISDN_OF_HLR_PLACE_HOLDER}-0"]
                SpmlData(
                    msisdn = msisdn,
                    isdnNumberOfVLR = vlrValues,
                    odboc = callBarringValues,
                    isMultiSim = hlrData == null || hlrData.value.isNullOrEmpty()
                )
            } else {
                null
            }
        } else {
            LOGGER.debug("No response found for number [$msisdn]")
            null
        }
    }

    override suspend fun multiSimCheckRequest(msisdn: String): SpmlData {
        LOGGER.info("Trying send multi sim member check request to msisdn [$msisdn]")
        try {
            val executionContext = ExecutionContext()
            val requestTemplate = RequestTemplate(MULTI_SIM_MEMBER_CHECK_REQUEST_TEMPLATE_NAME)
            val dataExtractPointMemberCheck = DataExtractPoint(MSISDN_OF_MEMBER_CHECK_PLACE_HOLDER, MSISDN_OF_MEMBER_CHECK_XPATH_PATTERN)
            executionContext.putString(REQUEST_MSISDN_PLACE_HOLDER, msisdn)
            requestTemplate.mandatoryDataExtractPointList = listOf(dataExtractPointMemberCheck)
            val sendRequest = sendRequest(requestTemplate, executionContext)
            val responses = if (sendRequest.isNotEmpty()) {
                sendRequest[0]
            } else {
                mapOf()
            }
            val msisdns = responses.mapNotNull { it.value.value }
            LOGGER.debug("Group msisdns [$msisdns] for parent msisdn [$msisdn]")
            return SpmlData(msisdn, isMultiSim = true, memberSimList = msisdns)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting SPML response for member check request", e)
            throw InternalErrorException(ConnectionError(e.message))
        }
    }

    override suspend fun sendRequest(requestTemplate: RequestTemplate, executionContext: ExecutionContext): List<Map<String, TagData>> {
        return coroutineScope {
            commandProcessor.process(listOf(requestTemplate), executionContext)
            executionContext.commandResponse.responses
        }
    }
}

