package hms.core.m1.rsc.rscservice.workflow

import hms.core.m1.rsc.rscservice.cache.CachedData
import hms.core.m1.rsc.rscservice.cache.DistributedMsisdnCacheManager
import hms.core.m1.rsc.rscservice.connectors.SpmlData
import hms.core.m1.rsc.rscservice.error.CommonStatus
import hms.core.m1.rsc.rscservice.error.InternalErrorException
import hms.core.m1.rsc.rscservice.logs.TransLogger
import hms.core.m1.rsc.rscservice.validator.*
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.http.HttpStatus
import org.springframework.stereotype.Component
import java.time.LocalDateTime
import jakarta.annotation.PostConstruct

interface WorkflowChain {
    suspend fun processRequest(context: Context): RoamingStatusCheckResult
}

data class Context(
    val traceId: String,
    val remoteIp: String,
    val hostIp: String,
    val apiUser: String,
    val msisdn: String,
    val version: String,
    val imsi: String?,
    val authenticated: Boolean = false,
    var roamingStatus: Boolean? = null,
    var vlrAddress: String? = null,
    var odboc: String? = null,
    var servedFromCache: Boolean = false,
    var multiSim: Boolean? = null,
    var childNumberRoaming: List<SpmlData> = listOf(),
    private val statusChain: HashMap<String, Boolean> = hashMapOf(),
    val receivedTimeMillis: Long = System.currentTimeMillis(),
    val receivedTime: LocalDateTime = LocalDateTime.now()
) {
    fun addToStatusChain(step: String, status: Boolean) {
        statusChain[step] = status
    }

    fun getStatusChain() = statusChain

    // Duplicate of this function is available in SpmlData class as well.
    fun isRoaming(callBarringStatusInactive: String, inactiveMsisdnRegex: String) =
        (odboc != null && odboc == callBarringStatusInactive) && !(vlrAddress == null || Regex(inactiveMsisdnRegex).matches(vlrAddress?: ""))
}

sealed interface RoamingStatusCheckResult
class RoamingStatusCheckSuccess(val respBody: ApiResponse) : RoamingStatusCheckResult
class RoamingStatusCheckFailure(val httpStatusCode: HttpStatus) : RoamingStatusCheckResult

data class ApiResponse(val roaming: Boolean)

@Component
class WorkflowChainImpl(
    val transLogger: TransLogger,
    val numberLengthValidator: NumberLengthValidator,
    val numberRangeValidator: NumberRangeValidator,
    val spmlExistsValidator: SpmlExistsValidator,
    val singleMsisdnRoamingValidator: SingleMsisdnRoamingValidator,
    val checkInCache: CheckInCache,
    val distributedMsisdnCacheManager: DistributedMsisdnCacheManager,
    val multiSimStatusValidator: MultiSimStatusValidator,
    @Value("\${service-api.msisdn-status-cache.enable-cache}") private val enableCache: Boolean,
    @Value("\${service-api.roaming-inactive-msisdn}") private val inactiveMsisdnRegex: String,
    @Value("\${service-api.call-barring-status-inactive}") private val callBarringStatusInactive: String
) : WorkflowChain {

    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(WorkflowChain::class.java)
    }

    @PostConstruct
    fun buildChain() {
        numberLengthValidator.setNextStep(numberRangeValidator)
        numberRangeValidator.setNextStep(checkInCache)
        checkInCache.setNextStep(spmlExistsValidator)
        spmlExistsValidator.setNextStep(singleMsisdnRoamingValidator)
        singleMsisdnRoamingValidator.setNextStep(multiSimStatusValidator)
    }

    override suspend fun processRequest(context: Context): RoamingStatusCheckResult {
        LOGGER.info("Start processing request [$context]")
        val result = try {
            val resp = numberLengthValidator.processRequest(context)
            LOGGER.info("Finished processing request for msisdn [${context.msisdn}] context[$context] result[$resp]")
            transLogger.printTransLog(context, resp)
            resp
        } catch (ex: Throwable) {
            val resp = WorkflowStepFailure(InternalErrorException(CommonStatus("Internal Error")))
            LOGGER.error("Unexpected error occurred", ex)
            transLogger.printTransLog(context, resp)
            resp
        }

        return when (result) {
            is WorkflowStepSuccess -> {
                addToCache(context)
                if (context.roamingStatus != null) {
                    RoamingStatusCheckSuccess(ApiResponse(context.roamingStatus!!))
                } else {
                    RoamingStatusCheckSuccess(ApiResponse(false))
                }
            }
            is WorkflowStepFailure -> RoamingStatusCheckFailure(result.error.status)
        }
    }

    private fun addToCache(context: Context) {
        if (context.roamingStatus == true && enableCache) {
            distributedMsisdnCacheManager.addToCache(
                context.msisdn, CachedData(
                    roamingStatus = context.roamingStatus == true,
                    multiSim = context.multiSim,
                    memberMsisdns = context.childNumberRoaming.map { it.msisdn },
                    vlrAddress = context.vlrAddress ?: "",
                )
            )
            if (context.multiSim == true) {
                context.childNumberRoaming
                    .filter { it.isRoaming(callBarringStatusInactive, inactiveMsisdnRegex) }
                    .forEach {
                        distributedMsisdnCacheManager.addToCache(
                            it.msisdn, CachedData(
                                roamingStatus = true,
                                multiSim = context.multiSim,
                                memberMsisdns = listOf(),
                                vlrAddress = it.isdnNumberOfVLR ?: "",
                            )
                        )
                    }
            }
        }
    }
}
